Section Pass2B.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Variables (F : bvmap 5 word) (fc : bv 32).
  Variable gd : Z.
  Hypothesis Hgd : 0 <= gd < 2 ^ 64.
  Variables (R : bvmap 5 word) (M : mem) (sp ret v conv lo shi : Z).

  Hypothesis Hra : getr R 1%bv = Z_to_bv 64 ret.
  Hypothesis Hret : ret_ok (Z_to_bv 64 ret).
  Hypothesis Hretr : 0 <= ret < 2 ^ 64.
  Hypothesis Hsp : getr R 2%bv = Z_to_bv 64 sp.
  Hypothesis Ha0 : getr R 10%bv = Z_to_bv 64 (sp + 416).
  Hypothesis Ha1 : getr R 11%bv = Z_to_bv 64 (sp + 3056).
  Hypothesis Ha2 : getr R 12%bv = Z_to_bv 64 sp.
  Hypothesis Ha3 : getr R 13%bv = Z_to_bv 64 (sp + 96).
  Hypothesis Ha4 : getr R 14%bv = Z_to_bv 64 (sp + 264).
  Hypothesis Hsplo : 2 ^ 32 <= sp - 608.
  Hypothesis Hsphi : sp + 3060 < 2 ^ 47.
  Hypothesis Hal : sp mod 16 = 0.
  Hypothesis HD : mdef M (sp - 608) 3668.
  Hypothesis Fap : fld SEGS M sp 8 (sp + 2928).
  Hypothesis Fv : fld SEGS M (sp + 2928) 8 v.
  Hypothesis Hv : 0 <= v < 2 ^ 64.
  Hypothesis F0 : fld SEGS M (sp + 3056) 1 37.
  Hypothesis F1 : fld SEGS M (sp + 3057) 1 108.
  Hypothesis F2 : fld SEGS M (sp + 3058) 1 conv.
  Hypothesis F3 : fld SEGS M (sp + 3059) 1 0.
  Hypothesis Hconv : conv = 117 \/ conv = 100 \/ conv = 120.
  Hypothesis Fflags : fld SEGS M (sp + 416) 4 0.
  Hypothesis Fwend : fld SEGS M (sp + 416 + 32) 8 (sp + 96).
  Hypothesis Fwpos : fld SEGS M (sp + 416 + 40) 8 (sp + 16).
  Hypothesis Flbf : fld SEGS M (sp + 416 + 144) 4 (2 ^ 32 - 1).
  Hypothesis ROC : mem_inv asegs M.
  Hypothesis RRC : relro_clear M.
  Hypothesis FCAN : fld SEGS M A_CANARY 8 gd.

  Hypothesis RF : rfull R.
  Hypothesis NI : ninv lo shi M.
  Hypothesis STK : stk asegs M lo sp.
  Hypothesis CEIL : aceil <= lo.
  Hypothesis LOS : lo + AINTRIN_STACK + 64 + 608 <= sp.
  Hypothesis SHI : sp + 3060 + 64 <= shi.
  Hypothesis Hre : ret mod 2 = 0.
  Hypothesis Hr48 : ret < 2 ^ 48.

  Let pcs := sp - 544.
  #[local] Abbreviation pcframe := (pcframe gd R sp ret).
  #[local] Abbreviation ffile := (ffile sp).
  #[local] Abbreviation stB := (stB gd R M sp ret).
  #[local] Abbreviation pcconst := (pcconst sp).

  Record stC (R3 : bvmap 5 word) (M3 : mem) (m nd pl : Z) : Prop := STC {
    c_st : stores_in (fun a => zwin (pcs - 64 - AINTRIN_STACK) sp a \/ zwin (sp + 416 + 40) (sp + 416 + 48) a \/ zwin sp (sp + 8) a) M M3;
    c_pf : pcframe M3;  c_ff : ffile M3 (sp + 16);
    c_112 : fld SEGS M3 (pcs + 112) 8 m; c_24 : fld SEGS M3 (pcs + 24) 8 pl; c_0 : fld SEGS M3 pcs 8 PREFIX_STR;
    c_r2 : getr R3 2%bv = Z_to_bv 64 pcs; c_r23 : getr R3 23%bv = Z_to_bv 64 (pcs + 176 - nd);
    c_r5 : getr R3 5%bv = Z_to_bv 64 0; c_r9 : getr R3 9%bv = Z_to_bv 64 2147483647; c_r18 : getr R3 18%bv = Z_to_bv 64 2147483647;
    c_r19 : getr R3 19%bv = Z_to_bv 64 0; c_r20 : getr R3 20%bv = Z_to_bv 64 (sp + 416); c_r21 : getr R3 21%bv = Z_to_bv 64 (sp + 3059);
    c_r22 : getr R3 22%bv = Z_to_bv 64 0; c_r24 : getr R3 24%bv = Z_to_bv 64 0; c_r25 : getr R3 25%bv = Z_to_bv 64 (2 ^ 64 - 1);
    c_r26 : getr R3 26%bv = Z_to_bv 64 0; c_r27 : getr R3 27%bv = Z_to_bv 64 1;
    c_r3 : getr R3 3%bv = getr R 3%bv; c_r4 : getr R3 4%bv = getr R 4%bv;
    c_nd : 0 <= nd <= 20; c_nd0 : nd = 0 <-> m = 0; c_m : 0 <= m < 2 ^ 64; c_pl : pl = 0 \/ pl = 1; c_nc : pl + nd <= 20;
    c_plz : pl = 0 \/ (conv = 100 /\ 2 ^ 63 <= v)   }.

  Definition knB (c : Z) : list kentry :=
      [KWr (SA (EVar 20) (-1024)) (ELit 3668); KRange (EVar 20) (2 ^ 32 + 1024) (2 ^ 47 - 2644); KAlign (EVar 20) 16;
       KRange (EVar 8) 37 37; KRange (EVar 9) 2147483647 2147483647; KRange (EVar 18) 2147483647 2147483647; KRange (EVar 19) 0 0;
       KRange (EVar 22) 0 0; KRange (EVar 26) 0 0;
       KWord (SA (EVar 20) 2640) (N.to_nat 1) (ELit 37); KWord (SA (EVar 20) 2641) (N.to_nat 1) (ELit 108);
       KWord (SA (EVar 20) 2642) (N.to_nat 1) (ELit c); KWord (SA (EVar 20) 2643) (N.to_nat 1) (ELit 0);
       KWord (SA (EVar 20) 0) (N.to_nat 4) (ELit 0);
       KWord (SA (EVar 20) (-416)) (N.to_nat 8) (EAlu ALU_ADD (EVar 20) (ELit 2512)); KWord (SA (EVar 20) 2512) (N.to_nat 8) (EVar 32);
       KWord (SA (EVar 20) (-960 + 72)) (N.to_nat 8) (EAlu ALU_ADD (EVar 20) (ELit (-416)));
       KWord (SA (EVar 20) (-960 + 80)) (N.to_nat 8) (ELit 0x12889); KWord (SA (EVar 20) (-960 + 48)) (N.to_nat 8) (ELit 0xfffffffffffeffff);
       KWord (SA (EVar 20) (-960 + 40)) (N.to_nat 8) (ELit MAGIC10_32); KWord (SA (EVar 20) (-960 + 104)) (N.to_nat 8) (ELit 0xccccccc);
       KImg 0x10000 0x17c000; KImg 0x17c000 0x185000].

  Lemma segB : forall R1 M1, stB R1 M1 -> exists R3 M3 m nd pl,
